        switch (id) {
            case 'chat':
            case 'quickchat':
                if (this.chatInputRef) { this._layoutChatInput(); this.chatInputRef.focus(); }
                break;
            case 'actions':
                this.handleAction('dance');
                break;
            case 'snowball':
                this.handleAction('throw');
                break;
            case 'map':
                this.toggleMap();
                break;
            case 'igloo':
                this.toggleClothes();
                break;
            case 'help':
                this.localPlayer && this.localPlayer.showChat('Precisa de ajuda? Visite a seccao Help!');
                break;
            case 'playercard':
                this.playerCard?.open(this.localPlayer);
                break;
            default:
                this.localPlayer && this.localPlayer.showChat(id);
        }
    }

    createCircularDockButton(x, y, iconChar, bgColor, callback) {
        const btn = this.add.container(x, y).setDepth(15001);
        const g = this.add.graphics();
        // Círculo com relevo Club Penguin
        g.fillStyle(bgColor, 1);
        g.fillCircle(0, 0, 11);
        g.lineStyle(1.5, 0xffffff, 0.85);
        g.strokeCircle(0, 0, 11);

        const icon = this.add.text(0, 0, iconChar, {
            fontSize: '11px',
            align: 'center'
        }).setOrigin(0.5);

        btn.add([g, icon]);
        btn.setSize(22, 22);
        btn.setInteractive(new Phaser.Geom.Circle(0, 0, 11), Phaser.Geom.Circle.Contains, { useHandCursor: true });

        btn.on('pointerdown', callback);
        return btn;
    }

    // Mapa da ilha: painel vetorial map.swf (IslandMap) — substitui o grid antigo
    createMapModal() {
        this.islandMap = new IslandMap(this);
    }

    toggleMap() {
        if (!this.mapOpen && this.clothesOpen) this.toggleClothes();
        if (this.playerCard?.isOpen) this.playerCard.close();
        this.mapOpen = !this.mapOpen;
        this.islandMap?.setOpen(this.mapOpen);
    }

    toggleClothes() {
        if (this.wardrobe?.isOpen) { this.wardrobe.close(); return; }
        if (this.mapOpen) this.toggleMap();
        if (this.playerCard?.isOpen) this.playerCard.close();
        this.clothesOpen = true;
        this.wardrobe.open(this.localPlayer);
    }

    // Carrega o pacote vetorial /assets/movies/<pack>/ (timelines.json + SVGs).
    // Sem fallback: se o pack nao carregar, mostra retangulo de erro.
    _initMovie(roomKey) {
        this._clearMovie();
        const pack = MOVIE_ROOM_MAP[roomKey];
        if (this.roomFailText) { this.roomFailText.destroy(); this.roomFailText = null; }
        if (!pack) { this._showRoomFail(roomKey); return; }
        this._movieReady = false;
        this.loadingScreen?.show(`Joining ${ROOM_NAMES[roomKey] || roomKey}...`, 0);
        MovieRoom.load(`/assets/movies/${pack}`)
            .then(async (movie) => {
                if (this.currentRoom !== roomKey) { return; } // sala trocou durante o load
                this.movie = movie;
                this.movie.setScale(this._ss);
                // decodifica todos os SVGs em paralelo — sem isso o primeiro
                // frame demora muito (decode lazy e sequencial por layer)
                for (const f of movie.files.keys()) movie._svgImage(f);
                this._buildMovieLayers();
                // bitmap de colisao (block_mc) + zonas de saida (triggers_mc)
                // atrasado para nao competir com o primeiro render das layers
                this.time.delayedCall(1500, () => {
                    if (this.movie === movie) movie.buildCollision(this._ss)
                        .catch((e) => console.warn('[movie] buildCollision', e));
                });
                // progresso da barra: fatia inicial pelo pack carregado,
                // o resto pelas layers rasterizadas
                const total = this.movieLayers.length;
                this.loadingScreen?.setProgress(0.15);
                const report = (done) => this.loadingScreen?.setProgress(0.15 + 0.85 * (done / total));
                // Tenta cache IndexedDB das layers ja rasterizadas (mesma
                // sala + mesma escala + mesmo pack). Hit = sala instantanea.
                const cacheKey = `v1|${pack}|ss${this._ss.toFixed(2)}|${movie.fingerprint()}`;
                const cached = await idbGet(cacheKey);
                let cacheHit = false;
                if (this.movie !== movie) return;
                if (cached?.blobs?.length === this.movieLayers.length) {
                    cacheHit = true;
                    for (let i = 0; i < this.movieLayers.length; i++) {
                        const layer = this.movieLayers[i];
                        try {
                            const bmp = await createImageBitmap(cached.blobs[i]);
                            layer.canvas.getContext('2d').drawImage(bmp, 0, 0);
                            bmp.close();
                        } catch { /* blob corrompido: cai no render normal */ }
                        this.textures.get(layer.texKey).refresh();
                    }
                }
                // Rasteriza as layers EM SEQUENCIA com yields: renderizar
                // todas em paralelo saturava a main thread (tela preta por
                // minutos + screenshot/browser travando). Sequencial mostra
                // o cenario progressivamente e mantem a UI responsiva.
                const boot = async () => {
                    let done = 0;
                    for (const layer of this.movieLayers) {
                        if (this.movie !== movie) return; // sala trocou
                        if (layer._busy) { await new Promise((r) => setTimeout(r, 30)); continue; }
                        layer._busy = true;
                        try {
                            await movie.renderLayer(layer.entry, layer.canvas, this._ss);
                        } catch (e) {
                            console.warn('[movie] renderLayer', e);
                        } finally {
                            this.textures.get(layer.texKey).refresh();
                            layer._busy = false;
                        }
                        done++;
                        report(done);
                        await new Promise((r) => setTimeout(r, 0));
                    }
                    // salva no cache para a proxima visita (so se nao houve hit)
                    if (!cacheHit && this.movie === movie) {
                        const blobs = [];
                        for (const layer of this.movieLayers) {
                            blobs.push(await canvasToBlob(layer.canvas));
                        }
                        if (blobs.every(Boolean) && this.movie === movie) {
                            idbPut(cacheKey, { blobs, ts: Date.now() });
                        }
                    }
                    this._movieReady = true;
                    this.loadingScreen?.hide();
                };
                if (!cacheHit) boot(); else { this._movieReady = true; this.loadingScreen?.hide(); }
                const frame = () => {
                    movie.tick();
                    // re-render so das layers com playhead ativo no frame —
                    // antes re-renderizava TUDO a cada tick (salas animadas
                    // ficavam injogaveis de tanto rasterizar)
                    const targets = this.movieLayers.filter((l) => movie._dirtyRoots.has(l.rootKey));
                    if (targets.length === 0) return;
                    for (const layer of targets) {
                        if (layer._busy) continue; // renderLayer async nao pode sobrepor
                        layer._busy = true;
                        layer.movie.renderLayer(layer.entry, layer.canvas, this._ss)
                            .catch((e) => console.warn('[movie] renderLayer', e))
                            .then(() => this.textures.get(layer.texKey).refresh())
                            .finally(() => { layer._busy = false; });
                    }
                };
                this.movieTimer = this.time.addEvent({ delay: 1000 / movie.rate, loop: true, callback: frame });
            })
            .catch((e) => {
                console.warn('[movie] falha ao carregar pack', pack, e);
                if (this.currentRoom === roomKey) this._showRoomFail(roomKey);
            });
    }

    // Sala vetorial indisponivel: cor lisa + aviso, em vez de PNG/SWL com
    // zonas de trigger e areas inacessiveis visiveis.
    _showRoomFail(roomKey) {
        this.loadingScreen?.hide();
        this.cameras.main.setBackgroundColor(0x263238);
        this.roomFailText = this.add.text(WORLD_W / 2, WORLD_H / 2,
            `Failed to load room "${roomKey}"\n(missing/corrupt SWF pack)`, {
            fontFamily: 'Arial, sans-serif',
            fontSize: '16px',
            color: '#eceff1',
            align: 'center',
            lineSpacing: 6,
        }).setOrigin(0.5).setDepth(950000);
    }

    _buildMovieLayers() {
        if (!this.movie) return;
        for (const layer of this.movieLayers || []) {
            layer.img.destroy();
            if (this.textures.exists(layer.texKey)) this.textures.remove(layer.texKey);
        }
        this.movieLayers = [];
        const cw = Math.round(WORLD_W * this._ss), ch = Math.round(WORLD_H * this._ss);
        this.movie.topLevelLayers().forEach((l, i) => {
            const canvas = document.createElement('canvas');
            canvas.width = cw; canvas.height = ch;
            const texKey = `movie_view_${this.movie.base.split('/').pop()}_${i}`;
            if (this.textures.exists(texKey)) this.textures.remove(texKey);
            this.textures.addCanvas(texKey, canvas);
            const img = this.add.image(WORLD_W / 2, WORLD_H / 2, texKey)
                .setDisplaySize(WORLD_W, WORLD_H)
                .setDepth(l.z + i * 0.001);
            this.movieLayers.push({
                movie: this.movie, entry: l.entry, canvas, texKey, img,
                rootKey: l.entry.name || `#${l.entry.depth}`,
            });
        });
    }

    _clearMovie() {
        if (this.movieTimer) { this.movieTimer.remove(); this.movieTimer = null; }
        if (this.movieLayers) {
            for (const layer of this.movieLayers) {
                layer.img.destroy();
                if (this.textures.exists(layer.texKey)) this.textures.remove(layer.texKey);
            }
            this.movieLayers = null;
        }
        this.movie = null;
        this.cameras.main.setBackgroundColor(0x000000);
    }

    changeRoom(newRoomKey, spawnX = null, spawnY = null) {
        if (this.currentRoom === newRoomKey) return;
        this.playerCard?.close();
        this.currentRoom = newRoomKey;
        this._clearMovie();
        this._initMovie(newRoomKey);

        const startX = spawnX ?? WORLD_W / 2;
        const startY = spawnY ?? WORLD_H * 0.65;
        this.localPlayer.setPosition(startX, startY);
        this.localPlayer.updateDepth();

        this.clearRemotePlayers();
        this.network.joinRoom(newRoomKey, startX, startY, this.localPlayer.gpaOutfit);

        if (this.mapOpen) {
            this.toggleMap();
        }
    }
}

// PenguinArt.js — pinguim vetorial do GoPenguin (/swf/penguin/ + clothing/sprites).
// Porta a logica da classe `bi` (Penguin) do cliente web:
//   - art = Clip da timeline principal (76 frames = poses/acoes)
//   - animationFrame = fh(look, frame) — "secret frames" por roupa equipada
//   - itens de roupa = Clips de /assets/clothing/<id>/, desenhados na ordem De
//   - cor do corpo via colorTransform solido (ve()): mult=0, add=rgb

import { MovieRoom } from "/src/movie/movie.js?t=1794156301387";
import { Clip } from "/src/movie/clip.js?t=1794159172294";

// Ordem de desenho dos itens (De no gp.js)
export const ITEM_DRAW_ORDER = ['feet', 'body', 'neck', 'hand', 'face', 'head'];
// Assinatura do look para penguin_action_frames (vr no gp.js)
const VR = ['head', 'face', 'neck', 'body', 'hand', 'feet'];

export const veColor = (rgb) => ({
    mult: [0, 0, 0, 1],
    add: [(rgb >> 16) & 255, (rgb >> 8) & 255, rgb & 255, 0],
});

export class PenguinLibrary {
    static async load(base = '/assets/movies/penguin') {
        const lib = new PenguinLibrary();
        lib.base = base;
        lib.movie = await MovieRoom.load(base);
        lib.movie.setScale(1);
        lib.actionData = await fetch('/assets/penguin-action-frames.json')
            .then((r) => (r.ok ? r.json() : {})).catch(() => ({}));
        // dh: actionFrame -> Map("head,face,neck,body,hand,feet" -> secret_frame)
        lib.dh = new Map();
        for (const [frame, list] of Object.entries(lib.actionData)) {
            const m = new Map();
            for (const t of list || []) {
                const sig = VR.map((o) => t[o] ?? 0).join(',');
                m.set(sig, t.secret_frame);
            }
            lib.dh.set(Number(frame), m);
        }
        lib.items = new Map();      // itemId -> Promise<Clip|null>
        lib.bounds = lib._unionBounds();
        // aquece todos os SVGs (decode assincrono; draw usa cache)
        for (const ch of Object.values(lib.movie.characters)) {
            if (ch.file) lib.movie._svgImage(ch.file).catch(() => {});
        }
        return lib;
    }

    // Clip base do pinguim (cada PenguinView instancia o seu)
    baseClip() { return new Clip(this.movie); }

    // bounds uniao de todos os frames (coords de mundo, y para cima = negativo)
    _unionBounds() {
        const clip = this.baseClip();
        const m = this.movie;
        let b = null;
        const main = m.data.main;
        for (let f = 1; f <= (main.frames?.length || 1); f++) {
            const entries = main.frames[f - 1] || [];
            const fb = clip._boundsOf(entries, { a: 1, b: 0, c: 0, d: 1, x: 0, y: 0 }, '');
            if (!fb) continue;
            b = b ? [Math.min(b[0], fb[0]), Math.min(b[1], fb[1]), Math.max(b[2], fb[2]), Math.max(b[3], fb[3])]
                  : fb;
        }
        if (!b) b = [-20, -60, 20, 10];
        // margem para poses maiores que a uniao inicial
        return { x0: Math.floor(b[0]) - 4, y0: Math.floor(b[1]) - 4,
                 x1: Math.ceil(b[2]) + 4, y1: Math.ceil(b[3]) + 4 };
    }

    get viewW() { return this.bounds.x1 - this.bounds.x0; }
    get viewH() { return this.bounds.y1 - this.bounds.y0; }

    // Carrega (lazy) o clip de um item de roupa; cache por id.
    itemClip(itemId) {
        if (!itemId) return Promise.resolve(null);
        if (!this.items.has(itemId)) {
            this.items.set(itemId, MovieRoom.load(`/assets/clothing/${itemId}`)
                .then((mv) => new Clip(mv))
                .catch(() => null));
        }
        return this.items.get(itemId);
    }

    // fh() do gp.js: frame real a desenhar dado look equipado + frame logico
    animationFrame(look, frame) {
        const max = this.movie.data.main?.frames?.length || 76;
        const s = this.dh.get(frame);
        if (!s) return frame;
        const sig = VR.map((o) => look[o] ?? 0).join(',');
        const i = s.get(sig);
        return i !== undefined && i <= max ? i : frame;
    }
}

// View de um pinguim: art + itens + estado de animacao.
// render() desenha num canvas 2D ja com transform de escala aplicado.
// Arte do balão de fala — port do layoutBalloon() do cliente web GoPenguin.
// Renderiza os masters (corpo sprite114, rabinho sprite156) sem o message_txt;
// a composição por mensagem segue a mesma matemática do original:
//   d = min(114, maxLineW + 4) + 14   (largura do balão)
//   f = nLines * 13.8 + 11            (altura do corpo)
//   corpo: scale (d/bw, f/bh) com base em y=-48.25 ; rabinho: scaleX=d/vw, y=-48.25
let _bubbleArtPromise = null;
export function bubbleArt(scene) {
    if (!_bubbleArtPromise) {
        _bubbleArtPromise = (async () => {
            const movie = scene.game._interfaceMoviePromise
                ? await scene.game._interfaceMoviePromise
                : await MovieRoom.load('/assets/movies/interface').then((m) => { m.setScale(1); return m; });
            if (!movie) return null;

            // fonte embarcada do editTexts (font 157 = Burbank Small Medium)
            try {
                const ff = new FontFace('BurbankSmallMedium', 'url(/assets/movies/interface/chars/font_157.ttf)');
                await ff.load();
                document.fonts.add(ff);
            } catch (e) { console.warn('[bubble] font', e); }

            const clip = new Clip(movie);
            const IDENT = { a: 1, b: 0, c: 0, d: 1, x: 0, y: 0 };
            const IDENT_COLOR = { mult: [1, 1, 1, 1], add: [0, 0, 0, 0] };
            const R = 3;

            async function master(spriteId) {
                const entries = movie.sprites[String(spriteId)]?.frames?.[0] || [];
                const b = clip._boundsOf(entries, IDENT, '');
                if (!b) return null;
                const canvas = document.createElement('canvas');
                canvas.width = Math.ceil((b[2] - b[0]) * R);
                canvas.height = Math.ceil((b[3] - b[1]) * R);
                const ctx = canvas.getContext('2d');
                ctx.setTransform(R, 0, 0, R, -b[0] * R, -b[1] * R);
                await clip._drawListFrame(ctx, entries, IDENT, '', IDENT_COLOR, R);
                return { canvas, bounds: b };
            }

            const body = await master(114);   // balloon_mc -> corpo
            const ptr = await master(156);    // pointer_mc -> faixa + rabinho
            if (!body || !ptr) return null;
            return { body, ptr, R };
        })().catch((e) => { console.warn('[bubble] art', e); return null; });
    }
    return _bubbleArtPromise;
}

// Quebra o texto em linhas como o original (wordWrap ~114px, fonte 12px).
export function bubbleLines(message) {
    const c = document.createElement('canvas').getContext('2d');
    c.font = '12px "BurbankSmallMedium", GoPenguin, Arial, sans-serif';
    const maxW = 114;
    const lines = [];
    for (const para of String(message).split(/\r\n|\r|\n/)) {
        let line = '';
        for (const word of para.split(' ')) {
            const cand = line ? line + ' ' + word : word;
            if (c.measureText(cand).width <= maxW || !line) { line = cand; continue; }
            lines.push(line); line = word;
            while (c.measureText(line).width > maxW && line.length > 1) {
                let cut = line.length - 1;
                while (cut > 1 && c.measureText(line.slice(0, cut)).width > maxW) cut--;
                lines.push(line.slice(0, cut));
                line = line.slice(cut);
            }
        }
        lines.push(line);
    }
    return lines;
}

export class PenguinView {
    constructor(lib, color = 0x0088ff) {
        this.lib = lib;
        this.art = lib.baseClip();
        this.art.set('body', { color: veColor(color) });
        this.art.set('ring', { visible: false });
        this.art.set('hotspot', { visible: false });
        this.items = new Map();       // slot -> Clip instance
        this.look = { head: 0, face: 0, neck: 0, body: 0, hand: 0, feet: 0 };
        this.frame = 1;
        this.drawnFrame = 0;
        this.dirty = true;
    }

    setColor(rgb) {
        this.art.set('body', { color: veColor(rgb) });
        this.dirty = true;
    }

    // look: {feet,body,neck,hand,face,head} -> itemId ou null
    setLook(look) {
        let changed = false;
        for (const slot of ITEM_DRAW_ORDER) {
            const id = look?.[slot] ? Number(look[slot]) : 0;
            if ((this.look[slot] || 0) === id) continue;
            this.look[slot] = id;
            changed = true;
            if (id) {
                this.lib.itemClip(id).then((clip) => {
                    if (!clip || this.look[slot] !== id) return;
                    const inst = clip.instance();
                    inst.set('ring', { visible: false });
                    this.items.set(slot, inst);
                    this.dirty = true;
                });
            } else {
                this.items.delete(slot);
            }
        }
        if (changed) this.dirty = true;
    }

    // frame: numero do frame logico da timeline principal (1..76)
    setFrame(frame) {
        const f = Math.max(1, Math.min(76, Math.round(frame) || 1));
        if (f === this.frame) return;
        this.frame = f;
        this.dirty = true;
    }

    get animationFrame() {
        return this.lib.animationFrame(this.look, this.frame);
    }

    // avanca sub-playheads (chamar ~24fps)
    advance() {
        this.art.advance();
        for (const it of this.items.values()) it.advance();
    }

    // desenha no ctx (transform de scale ja aplicada pelo chamador)
    async render(ctx, scale) {
        const af = this.animationFrame;
        if (this.drawnFrame !== af) {
            this.art.resetPlayback();
            for (const it of this.items.values()) it.resetPlayback();
            this.drawnFrame = af;
        }
        await this.art.draw(ctx, af, scale);
        for (const slot of ITEM_DRAW_ORDER) {
            const it = this.items.get(slot);
            if (it) await it.draw(ctx, af, scale);
        }
        this.dirty = false;
    }
}

/**
 * NetworkClient.js - Gerenciador WebSocket para o Club Penguin Phaser
 * Contrato de rede conforme especificação AGENTS.md / QWEN.md
 */

export default class NetworkClient {
    constructor(scene) {
        this.scene = scene;
        this.socket = null;
        this.isConnected = false;
        this.playerId = 'Penguin_' + Math.floor(Math.random() * 8999 + 1000);
        this.reconnectTimer = null;

        // Endereço do WebSocket Server local (porta 8080)
        const host = window.location.hostname || 'localhost';
        this.url = `ws://${host}:8080`;

        this.connect();
    }

    connect() {
        if (this.socket && (this.socket.readyState === WebSocket.OPEN || this.socket.readyState === WebSocket.CONNECTING)) {
            return;
        }

        console.log(`[NetworkClient] Conectando a ${this.url}...`);
        this.socket = new WebSocket(this.url);

        this.socket.onopen = () => {
            console.log('[NetworkClient] Conectado ao servidor WebSocket com sucesso!');
            this.isConnected = true;
            if (this.reconnectTimer) {
                clearTimeout(this.reconnectTimer);
                this.reconnectTimer = null;
            }
            this.scene.events.emit('net-connected', { playerId: this.playerId });
        };

        this.socket.onmessage = (event) => {
            try {
                const packet = JSON.parse(event.data);
                this.handlePacket(packet);
            } catch (err) {
                console.error('[NetworkClient] Erro ao decodificar pacote JSON:', err, event.data);
            }
        };

        this.socket.onclose = () => {
            console.warn('[NetworkClient] Conexão encerrada. Tentando reconectar em 3s...');
            this.isConnected = false;
            this.scene.events.emit('net-disconnected');
            this.scheduleReconnect();
        };

        this.socket.onerror = (error) => {
            console.error('[NetworkClient] Erro no socket:', error);
        };
    }

    scheduleReconnect() {
        if (!this.reconnectTimer) {
            this.reconnectTimer = setTimeout(() => {
                this.reconnectTimer = null;
                this.connect();
            }, 3000);
        }
    }

    send(op, data = {}) {
        if (!this.isConnected || !this.socket || this.socket.readyState !== WebSocket.OPEN) {
            console.warn(`[NetworkClient] Não foi possível enviar ${op}: socket desconectado.`);
            return;
        }
        const packet = JSON.stringify({ op, data });
        this.socket.send(packet);
    }

    // Ações do Jogador conforme protocolo AGENTS.md
    joinRoom(roomId = 'town', x = 400, y = 300, paperdoll = null) {
        this.send('JOIN_ROOM', {
            playerId: this.playerId,
            roomId,
            x,
            y,
            paperdoll
        });
    }

    sendEquip(slot, itemId) {
        this.send('EQUIP_ITEM', {
            playerId: this.playerId,
            slot,
            itemId: itemId || null
        });
    }

    sendMove(targetX, targetY) {
        this.send('MOVE_PLAYER', {
            playerId: this.playerId,
            targetX: Math.round(targetX),
            targetY: Math.round(targetY)
        });
    }

    sendColor(color) {
        this.send('SET_COLOR', {
            playerId: this.playerId,
            color: Math.round(color) & 0xffffff
        });
    }

    sendChat(message) {
        if (!message || !message.trim()) return;
        this.send('SEND_CHAT', {
            playerId: this.playerId,
            message: message.trim()
        });
    }

    // Processamento de pacotes recebidos e emissão de eventos no Phaser
    handlePacket(packet) {
        const { op, data } = packet;
        if (!op) return;

        switch (op) {
            case 'JOIN_ROOM':
            case 'ROOM_STATE':
                this.scene.events.emit('room-state', data);
                break;
            case 'MOVE_PLAYER':
                this.scene.events.emit('player-move', data);
                break;
            case 'SEND_CHAT':
                this.scene.events.emit('player-chat', data);
                break;
            case 'EQUIP_ITEM':
                this.scene.events.emit('player-equip', data);
                break;
            case 'SET_COLOR':
                this.scene.events.emit('player-color', data);
                break;
