            position: 'fixed',
            border: 'none', outline: 'none',
            background: 'transparent',
            color: '#ffffff',
            fontFamily: "'GoPenguin', Arial, sans-serif",
            fontSize: '14px',
            zIndex: '9999',
            boxSizing: 'border-box',
            display: 'none',
