// + manifesto dos itens com arte local (paper/<id>).
// type -> slot do paperdoll: 2=head 3=face 4=neck 5=body 6=hand 7=feet
// 8=flag 9=background (nao equipaveis no paperdoll lateral) 1=cor do pinguim

const TYPE_TO_SLOT = { 2: 'head', 3: 'face', 4: 'neck', 5: 'body', 6: 'hand', 7: 'feet' };

let _catalog = null;
let _manifest = null;

export async function loadCatalog() {
    if (_catalog) return _catalog;
    const [itemsRes, manifestRes] = await Promise.all([
        fetch('/assets/items.json').then((r) => (r.ok ? r.json() : [])).catch(() => []),
        fetch('/assets/paper/index.json').then((r) => (r.ok ? r.json() : [])).catch(() => []),
    ]);
    const byId = new Map(itemsRes.map((i) => [i.id, i]));
    _manifest = new Set(manifestRes);
    _catalog = { byId, manifest: _manifest };
    return _catalog;
}

// itens equipaveis que temos arte local: [{id,name,type,slot}]
export async function wardrobeItems() {
    const { byId, manifest } = await loadCatalog();
    const out = [];
    for (const id of manifest) {
        const it = byId.get(id);
        if (!it || !it.name) continue;
        const slot = TYPE_TO_SLOT[it.type];
        if (!slot) continue;
        out.push({ id, name: it.name, type: it.type, slot });
    }
    return out.sort((a, b) => a.type - b.type || a.name.localeCompare(b.name));
}

